INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (12, 3, 'Haz un INNER JOIN entre aventureros (a) y equipamiento (e). Une ambas usando "id_aventurero" y muestra el "nombre" del héroe y el "item" que porta.', 'SELECT a.nombre, e.item FROM aventureros a INNER JOIN equipamiento e ON a.id_aventurero = e.id_aventurero;', 3, NULL, '3.1: Cruzando el Puente (INNER JOIN)', 1, 'HISTORIA', 'editor') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (13, 3, 'Haz el mismo JOIN de la misión anterior, pero agrega un filtro (WHERE) para mostrar únicamente los items de la clase ''Caballero''.', 'SELECT a.nombre, e.item FROM aventureros a INNER JOIN equipamiento e ON a.id_aventurero = e.id_aventurero WHERE a.clase = ''Caballero'';', 4, NULL, '3.2: Arsenal Específico', 2, 'HISTORIA', 'editor') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (14, 3, 'Usa un LEFT JOIN desde aventureros hacia equipamiento para mostrar los nombres de TODOS los héroes, incluso si no tienen armas compradas.', 'SELECT a.nombre, e.item FROM aventureros a LEFT JOIN equipamiento e ON a.id_aventurero = e.id_aventurero;', 4, NULL, '3.3: Nadie se Queda Atrás (LEFT JOIN)', 3, 'HISTORIA', 'editor') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (15, 3, 'Une ambas tablas. Muestra el "nombre", usa SUM(precio) para calcular el valor total de sus armas, y usa GROUP BY para agrupar por nombre.', 'SELECT a.nombre, SUM(e.precio) FROM aventureros a INNER JOIN equipamiento e ON a.id_aventurero = e.id_aventurero GROUP BY a.nombre;', 5, NULL, '3.4: El Valor de un Héroe', 4, 'HISTORIA', 'editor') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (16, 4, 'Demuestra tu comprensión abstracta. Diseña el diagrama Entidad-Relación. Crea al menos dos Entidades y conéctalas con una Llave Foránea.', '{"diagrama": "validado"}', 5, NULL, 'Fase 1: El Lienzo del Arquitecto', 1, 'HISTORIA', 'diagram') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (17, 4, 'Último reto de código. Une aventureros y equipamiento, filtra aquellos que tengan un item con precio MAYOR a 100. Muestra el nombre y el item.', 'SELECT a.nombre, e.item FROM aventureros a INNER JOIN equipamiento e ON a.id_aventurero = e.id_aventurero WHERE e.precio > 100;', 5, NULL, 'Fase 2: Extracción Maestra', 2, 'HISTORIA', 'editor') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (10, 2, 'Loya ha entrenado duro. Usa UPDATE para cambiar su nivel a 20 en la tabla aventureros. Usa "RETURNING *" al final para verificar el cambio.', 'UPDATE aventureros SET nivel = 20 WHERE nombre = ''Loya'' RETURNING *;', 3, NULL, '2.3: UPDATE - Cambiar el Destino', 3, 'HISTORIA', 'editor') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (11, 2, 'El asesino Dan nos ha traicionado. Usa DELETE para borrarlo de la tabla aventureros. Recuerda usar WHERE y "RETURNING *" al final.', 'DELETE FROM aventureros WHERE nombre = ''Dan'' RETURNING *;', 3, NULL, '2.4: DELETE - El Abismo', 4, 'HISTORIA', 'editor') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (23, 2, 'Busca el arma más barata. Usa la función MIN(precio) en la tabla equipamiento.', 'SELECT MIN(precio) FROM equipamiento;', 2, NULL, 'Práctica Relámpago: Ganga', 101, 'RAPIDA', 'editor') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (24, 2, '¿Cuál es la media de nuestro gremio? Calcula el promedio de nivel usando AVG(nivel) en la tabla aventureros.', 'SELECT AVG(nivel) FROM aventureros;', 2, NULL, 'Práctica Relámpago: Promedio de Poder', 102, 'RAPIDA', 'editor') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (25, 2, 'Encuentra el valor del arma más cara usando MAX(precio) en el equipamiento.', 'SELECT MAX(precio) FROM equipamiento;', 2, NULL, 'Práctica Relámpago: Objeto de Lujo', 103, 'RAPIDA', 'editor') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (26, 2, 'Cuenta cuántos objetos en total tenemos guardados usando COUNT(*) en la tabla equipamiento.', 'SELECT COUNT(*) FROM equipamiento;', 1, NULL, 'Práctica Relámpago: Inventario Total', 104, 'RAPIDA', 'editor') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (27, 2, '¿Quién es el más fuerte de cada clase? Muestra la "clase" y el MAX(nivel), agrupando por clase.', 'SELECT clase, MAX(nivel) FROM aventureros GROUP BY clase;', 4, NULL, 'Práctica Relámpago: Cima de Clases', 105, 'RAPIDA', 'editor') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (28, 4, 'Diseña el sistema completo de una Posada de Aventureros. Crea 3 entidades: ''huespedes'', ''habitaciones'' y ''reservas''. Cada una con al menos 2 atributos. Conecta huéspedes con reservas, y habitaciones con reservas.', '{"diagrama": "validado"}', 5, '{"mensaje_error": "La posada necesita entidades para los huéspedes, las habitaciones y las reservas.", "min_atributos": 6, "min_entidades": 3, "min_relaciones": 2, "mensaje_relaciones": "Conecta huéspedes con reservas, y habitaciones con reservas (relación muchos a muchos).", "entidades_requeridas": [["huesped", "huespedes", "cliente", "clientes"], ["habitacion", "habitaciones", "cuarto", "cuartos", "room"], ["reserva", "reservas", "reservacion", "booking"]]}', 'Fase 1: La Posada del Arquitecto', 1, 'HISTORIA', 'diagram') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (29, 4, 'Demuestra tu dominio de JOINs. Une aventureros y equipamiento, filtra los items con precio mayor a 100. Muestra nombre, item y precio ordenados por precio de mayor a menor.', 'SELECT a.nombre, e.item, e.precio FROM aventureros a INNER JOIN equipamiento e ON a.id_aventurero = e.id_aventurero WHERE e.precio > 100 ORDER BY e.precio DESC;', 5, NULL, 'Fase 2: Consulta Maestra', 2, 'HISTORIA', 'editor') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (104, 1, 'El Gran salón contiene TODOS los aventureros. Imagina el Gran Salón del Gremio donde están TODOS. Tu misión es usar el asterisco (*) para mirar al Universo completo.', 'SELECT * FROM aventureros;', 1, '{"wordBank": ["SELECT", "*", "FROM", "aventureros", ";", "WHERE", "clase"]}', '1.1: El Conjunto Universo', 1, 'HISTORIA', 'drag_drop') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (30, 4, 'Reto final: muestra un ranking de héroes por su gasto total en equipo. Usa INNER JOIN, SUM(e.precio), GROUP BY, y ordena de mayor a menor gasto. Muestra nombre y total.', 'SELECT a.nombre, SUM(e.precio) AS total FROM aventureros a INNER JOIN equipamiento e ON a.id_aventurero = e.id_aventurero GROUP BY a.nombre ORDER BY total DESC;', 5, NULL, 'Fase 3: El Ranking Definitivo', 3, 'HISTORIA', 'editor') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (37, 3, '¡Has diseñado el plano! Ahora, forja la tabla "pociones" con id (SERIAL PK), nombre (VARCHAR 50) y poder (INTEGER).', 'CREATE TABLE pociones (id SERIAL PRIMARY KEY, nombre VARCHAR(50), poder INTEGER);', 3, '{"tipo_validacion": "ddl"}', '3.4: Forjando el Metal (DDL)', 4, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (38, 3, '¡Cuidado! Olvidamos la columna "rareza". Añádela a la tabla "pociones" (VARCHAR 20).', 'ALTER TABLE pociones ADD COLUMN rareza VARCHAR(20);', 3, '{"tipo_validacion": "ddl"}', '3.5: Reforzando la Armadura (ALTER)', 5, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (40, 4, 'Diseña la Posada: Huespedes, Habitaciones y Reservas.', '{"diagrama": "validado"}', 4, '{"min_entidades": 3, "min_relaciones": 2}', 'Reto Final Fase 1: El Plano', 7, 'HISTORIA', 'diagram') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (41, 4, 'Crea la tabla "habitaciones" (id SERIAL PK, numero INTEGER, precio NUMERIC).', 'CREATE TABLE habitaciones (id SERIAL PRIMARY KEY, numero INTEGER, precio NUMERIC);', 4, '{"tipo_validacion": "ddl"}', 'Reto Final Fase 2: Construcción', 8, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (42, 4, 'Une Huespedes con Habitaciones para el reporte diario.', 'SELECT h.nombre, hab.numero FROM huespedes h JOIN reservas r ON h.id = r.id_huesped JOIN habitaciones hab ON r.id_habitacion = hab.id;', 5, '{}', 'Reto Final Fase 3: Consultas', 9, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (9, 2, 'Agrega un nuevo registro. Inserta al aventurero ''Gimli'', clase ''Guerrero'', nivel 10 en la tabla aventureros. Agrega "RETURNING *" al final para ver a tu creación.', 'INSERT INTO aventureros (nombre, clase, nivel) VALUES (''Gimli'', ''Guerrero'', 10) RETURNING *;', 2, NULL, '2.1: CREATE - El Aliento de Vida', 1, 'HISTORIA', 'editor') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (111, 2, 'La ''R'' de CRUD significa Read (Leer). Usa SELECT para encontrar a todos los aventureros que tengan un nivel mayor a 10.', 'SELECT * FROM aventureros WHERE nivel > 10;', 1, NULL, '2.2: READ - La Visión del Oráculo', 2, 'HISTORIA', 'editor') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (112, 2, 'Usa LIKE y el comodín % para encontrar a los aventureros cuyo nombre empiece con la letra "A".', 'SELECT * FROM aventureros WHERE nombre LIKE ''A%'';', 2, NULL, '2.5: El Detective (LIKE)', 5, 'HISTORIA', 'editor') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (113, 2, 'Frena la avalancha de datos. Trae a los 3 aventureros con mayor nivel ordenándolos de forma descendente (DESC).', 'SELECT * FROM aventureros ORDER BY nivel DESC LIMIT 3;', 2, NULL, '2.6: Orden y Límite', 6, 'HISTORIA', 'editor') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (107, 1, 'El Rey llama a la guerra. Cualquiera que sea Mago O Arquero entra al grupo. Une ambos conjuntos.', 'SELECT * FROM aventureros WHERE clase = ''Mago'' OR clase = ''Arquero'';', 1, '{"wordBank": ["SELECT", "*", "FROM", "aventureros", "WHERE", "clase", "=", "''Mago''", "OR", "''Arquero''", "AND", "''Guerrero''", ";"]}', '1.4: La Unión - OR', 4, 'HISTORIA', 'drag_drop') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (108, 1, 'Ha habido un robo. Sospechamos de todos EXCEPTO de los Paladines. Usa el símbolo != (distinto de) para excluirlos del conjunto.', 'SELECT * FROM aventureros WHERE clase != ''Paladin'';', 1, '{"wordBank": ["SELECT", "*", "FROM", "aventureros", "WHERE", "clase", "!=", "''Paladin''", "=", "''Mago''", ";"]}', '1.5: La Diferencia - NOT/!=', 5, 'HISTORIA', 'drag_drop') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (105, 1, 'De todos los del Gran Salón, queremos que los Magos den un paso al frente. Usa WHERE para crear este Subconjunto.', 'SELECT * FROM aventureros WHERE clase = ''Mago'';', 1, '{"wordBank": ["SELECT", "*", "FROM", "aventureros", "WHERE", "clase", "=", "''Mago''", "''Guerrero''", ";"]}', '1.2: El Subconjunto - Filtrado', 2, 'HISTORIA', 'drag_drop') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (106, 1, 'Queremos a los héroes de élite. Deben pertenecer al conjunto de GUERREROS Y además tener un nivel mayor a 20 (> 20).', 'SELECT * FROM aventureros WHERE clase = ''Guerrero'' AND nivel > 20;', 1, '{"wordBank": ["SELECT", "*", "FROM", "aventureros", "WHERE", "clase", "=", "''Guerrero''", "AND", "nivel", ">", "20", "OR", "10", ";"]}', '1.3: La Intersección - AND', 3, 'HISTORIA', 'drag_drop') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (109, 1, 'Filtremos más a fondo. Encuentra a los Guerreros que tengan un nivel mayor a 15 Y que también tengan nivel menor a 30.', 'SELECT * FROM aventureros WHERE clase = ''Guerrero'' AND nivel > 15 AND nivel < 30;', 1, '{"wordBank": ["SELECT", "*", "FROM", "aventureros", "WHERE", "clase", "=", "''Guerrero''", "AND", "nivel", ">", "15", "<", "30", "OR", ";"]}', '1.6: Múltiples Intersecciones', 6, 'HISTORIA', 'drag_drop') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (110, 1, 'Selecciona a los que sean Mago, Arquero o Guerrero. Puedes usar múltiples OR, o intentar usar la función IN(...) para atrapar a los tres grupos.', 'SELECT * FROM aventureros WHERE clase IN (''Mago'', ''Arquero'', ''Guerrero'');', 1, '{"wordBank": ["SELECT", "*", "FROM", "aventureros", "WHERE", "clase", "IN", "(", "''Mago''", ",", "''Arquero''", "''Guerrero''", ")", "OR", ";"]}', '1.7: Múltiples Uniones - IN', 7, 'HISTORIA', 'drag_drop') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (39, 3, 'La tabla "trastos_viejos" no sirve. Elíminala del registro para siempre.', 'DROP TABLE trastos_viejos;', 2, '{"regex_esperado": "DROP\\s+TABLE\\s+trastos_viejos\\s*;", "tipo_validacion": "TEXTUAL"}', '3.6: El Desvío del Abismo (DROP)', 6, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (80, 15, 'Inserta un nuevo aventurero (implícito COMMIT).', 'BEGIN; INSERT INTO aventureros (nombre, clase, nivel) VALUES (''Temporal1'', ''Guerrero'', 50); COMMIT; SELECT * FROM aventureros WHERE nombre = ''Temporal1'';', 3, '{"foco": ["BEGIN", "COMMIT", "visibilidad"], "modo": "terminal_transaccional", "paneles": ["sesion_a", "sesion_b", "linea_tiempo", "aislamiento"], "tipo_validacion": "transaccion", "mensaje_terminal": "Inserta como si estuvieras en psql real: primero abre la transacción, luego ejecuta el cambio y confirma para hacerlo visible a otras sesiones.", "sesiones_paralelas": true, "terminal_prompt_tx": "dagon=*#", "terminal_prompt_base": "dagon=#"}', '15.1: Insert y Commit', 1, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (81, 15, 'Inserta y deshaz los cambios.', 'BEGIN; INSERT INTO aventureros (nombre, clase) VALUES (''Desechado'', ''Mago''); ROLLBACK; SELECT COUNT(*) FROM aventureros WHERE nombre = ''Desechado'';', 3, '{"foco": ["BEGIN", "ROLLBACK", "estado_confirmado"], "modo": "terminal_transaccional", "paneles": ["sesion_a", "sesion_b", "linea_tiempo", "rollback_total"], "tipo_validacion": "transaccion", "mensaje_terminal": "Piensa en ROLLBACK como regresar al último estado confirmado. La otra sesión nunca alcanza a ver lo que quedó pendiente.", "sesiones_paralelas": true, "terminal_prompt_tx": "dagon=*#", "terminal_prompt_base": "dagon=#"}', '15.2: ROLLBACK', 2, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (82, 15, 'Usa SAVEPOINT para hacer rollback parcial.', 'BEGIN; INSERT INTO aventureros (nombre, clase) VALUES (''Primero'', ''Guerrero''); SAVEPOINT sp1; INSERT INTO aventureros (nombre, clase) VALUES (''Segundo'', ''Mago''); ROLLBACK TO SAVEPOINT sp1; COMMIT; SELECT COUNT(*) FROM aventureros WHERE nombre IN (''Primero'', ''Segundo'');', 5, '{"foco": ["SAVEPOINT", "ROLLBACK TO SAVEPOINT", "COMMIT"], "modo": "terminal_transaccional", "paneles": ["sesion_a", "sesion_b", "linea_tiempo", "savepoint"], "tipo_validacion": "transaccion", "mensaje_terminal": "Esta misión enseña rollback parcial: conserva la parte correcta de la transacción y deshaz solo el bloque posterior al savepoint.", "sesiones_paralelas": true, "terminal_prompt_tx": "dagon=*#", "terminal_prompt_base": "dagon=#"}', '15.3: SAVEPOINT', 3, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (52, 7, 'Muestra el último valor usado por la secuencia.', 'SELECT currval(''aventureros_id_aventurero_seq'');', 2, '{"tipo_validacion": "ddl"}', '7.2: Currval de secuencia', 2, 'HISTORIA', 'editor') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (53, 7, 'Crea una secuencia llamada "seq_custom" que empiece en 100.', 'CREATE SEQUENCE seq_custom START 100; SELECT nextval(''seq_custom'');', 3, '{"tipo_validacion": "ddl"}', '7.3: Crear secuencia manual', 3, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (54, 7, 'Elimina la secuencia seq_custom.', 'DROP SEQUENCE seq_custom;', 2, '{"tipo_validacion": "ddl"}', '7.4: Eliminar secuencia', 4, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (45, 5, 'Inserta un aventurero llamado ''Nuevo'' con la clase ''Guerrero'' sin especificar su nivel. Verifica que use DEFAULT 1.', 'INSERT INTO aventureros (nombre, clase) VALUES (''Nuevo'', ''Guerrero'') RETURNING *;', 2, NULL, '5.3: El DEFAULT del novato', 3, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (46, 5, 'El gremio necesita un listado oficial. Selecciona todos los datos de la tabla "aventureros", pero filtra los resultados para mostrar ÚNICAMENTE a aquellos cuyo nombre no esté vacío utilizando la condición IS NOT NULL.', 'SELECT * FROM aventureros WHERE nombre IS NOT NULL;', 2, NULL, '5.4: Valores obligatorios', 4, 'HISTORIA', 'editor') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (51, 7, 'Las secuencias son "generadores de tickets" invisibles en SQL. Cuando usas SERIAL, PostgreSQL crea una por ti. Usa la función nextval(''nombre_secuencia'') para pedirle a la base de datos el siguiente número disponible en la fila.', 'SELECT nextval(''aventureros_id_aventurero_seq'');', 2, '{"tipo_validacion": "ddl"}', '7.1: Ver siguiente serial', 1, 'HISTORIA', 'editor') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (43, 5, 'Crea la tabla "mascotas" con: id (SERIAL, PK), nombre (VARCHAR 50, NOT NULL) y nivel (INTEGER DEFAULT 1).', 'CREATE TABLE mascotas (id SERIAL PRIMARY KEY, nombre VARCHAR(50) NOT NULL, nivel INTEGER DEFAULT 1);', 2, NULL, '5.1: Crear tabla con sellos', 1, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (44, 5, 'Añade PRIMARY KEY a la columna id_aventurero de la tabla aventureros.', 'ALTER TABLE aventureros ADD CONSTRAINT aventureros_pkey PRIMARY KEY (id_aventurero);', 3, NULL, '5.2: Añadir constraint PK', 2, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (47, 6, 'Añade constraint UNIQUE a la columna nombre de aventureros.', 'ALTER TABLE aventureros ADD CONSTRAINT aventureros_nombre_unique UNIQUE (nombre);', 3, NULL, '6.1: Nombres únicos', 1, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (48, 6, 'Añade CHECK para que nivel sea entre 1 y 99.', 'ALTER TABLE aventureros ADD CONSTRAINT aventureros_nivel_check CHECK (nivel >= 1 AND nivel <= 99);', 3, NULL, '6.2: CHECK nivel válido', 2, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (49, 6, 'Añade CHECK para que precio sea mayor a 0 en equipamiento.', 'ALTER TABLE equipamiento ADD CONSTRAINT equipamiento_precio_check CHECK (precio > 0);', 3, NULL, '6.3: CHECK precio positivo', 3, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
