INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (50, 6, 'El gremio necesita registrar una nueva habitación (numero: 999, tipo: ''Especial''). Ingrésala sin especificar el precio para aprovechar nuestro valor por defecto. IMPORTANTE: Necesitamos ver el comprobante inmediatamente. Haz que tu instrucción de inserción "retorne" todos los datos generados (*) al finalizar.', 'INSERT INTO habitaciones (numero, tipo) VALUES (999, ''Especial'') RETURNING *;', 2, '{"tipo_validacion": "ddl"}', '6.4: DEFAULT automático', 4, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (70, 11, 'Busca aventureros que NO empiecen con "A".', 'SELECT * FROM aventureros WHERE nombre NOT LIKE ''A%'';', 2, NULL, '11.4: NOT LIKE', 4, 'HISTORIA', 'editor') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (71, 12, 'Crea función "sumar" que sume dos números.', 'CREATE FUNCTION sumar(a INTEGER, b INTEGER) RETURNS INTEGER AS '' SELECT a + b; '' LANGUAGE SQL; SELECT sumar(5, 3);', 3, NULL, '12.1: Función básica', 1, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (72, 12, 'Crea función que cuente aventureros por clase.', 'CREATE FUNCTION contar_por_clase(clase_param VARCHAR) RETURNS INTEGER AS '' SELECT COUNT(*) FROM aventureros WHERE clase = clase_param; '' LANGUAGE SQL; SELECT contar_por_clase(''Guerrero'');', 4, NULL, '12.2: Contar aventureros', 2, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (73, 12, 'Crea función que diga si el nivel es alto (>20) o bajo.', 'CREATE FUNCTION verificar_nivel(n INTEGER) RETURNS TEXT AS '' SELECT CASE WHEN n > 20 THEN ''Alto'' ELSE ''Bajo'' END; '' LANGUAGE SQL; SELECT verificar_nivel(25);', 4, NULL, '12.3: Función con IF', 3, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (74, 12, 'Crea función que devuelva aventureros con nivel mayor al dado.', 'CREATE FUNCTION aventureros_fuertes(min_nivel INTEGER) RETURNS TABLE(nombre TEXT, nivel INTEGER) AS '' SELECT nombre, nivel FROM aventureros WHERE nivel >= min_nivel; '' LANGUAGE SQL; SELECT * FROM aventureros_fuertes(20);', 5, NULL, '12.4: Función con tabla', 4, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (75, 13, 'Crea función que inserte aventurero y devuelva mensaje.', 'CREATE FUNCTION crear_aventurero(n VARCHAR, c VARCHAR) RETURNS TEXT AS '' BEGIN INSERT INTO aventureros (nombre, clase) VALUES (n, c); RETURN ''Aventurero '' || n || '' creado!''; END; '' LANGUAGE plpgsql; SELECT crear_aventurero(''Test'', ''Mago'');', 4, NULL, '13.1: Procedure insertar', 1, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (76, 13, 'Crea función que inserte aventurero Y su equipo.', 'CREATE FUNCTION reclutar_con_equipo(av_nombre VARCHAR, av_clase VARCHAR, eq_item VARCHAR, eq_precio INTEGER) RETURNS INTEGER AS '' DECLARE new_id INTEGER; BEGIN INSERT INTO aventureros (nombre, clase) VALUES (av_nombre, av_clase) RETURNING id_aventurero INTO new_id; INSERT INTO equipamiento (id_aventurero, item, precio) VALUES (new_id, eq_item, eq_precio); RETURN new_id; END; '' LANGUAGE plpgsql;', 5, NULL, '13.2: Transacción múltiples inserts', 2, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (78, 14, 'Crea tabla de logs y trigger de auditoría.', 'CREATE TABLE log_cambios (id SERIAL, accion TEXT, tabla TEXT, fecha TIMESTAMP DEFAULT NOW()); CREATE FUNCTION fn_auditar() RETURNS TRIGGER AS '' BEGIN INSERT INTO log_cambios (accion, tabla) VALUES (TG_OP, TG_TABLE_NAME); RETURN NEW; END; '' LANGUAGE plpgsql; CREATE TRIGGER trg_auditar AFTER INSERT ON aventureros FOR EACH ROW EXECUTE FUNCTION fn_auditar();', 5, NULL, '14.2: Trigger con auditoría', 2, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (79, 14, 'Crea trigger BEFORE que valide nivel antes de insertar.', 'CREATE FUNCTION fn_validar_nivel() RETURNS TRIGGER AS '' BEGIN IF NEW.nivel < 1 OR NEW.nivel > 99 THEN RAISE EXCEPTION ''Nivel debe estar entre 1 y 99''; END IF; RETURN NEW; END; '' LANGUAGE plpgsql; CREATE TRIGGER trg_validar_nivel BEFORE INSERT ON aventureros FOR EACH ROW EXECUTE FUNCTION fn_validar_nivel();', 5, NULL, '14.3: Trigger BEFORE validación', 3, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
