INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (94, 20, 'Crea tabla "bestiario" con PK, NOT NULL, CHECK.', 'CREATE TABLE bestiario (id SERIAL PRIMARY KEY, nombre VARCHAR(100) NOT NULL, nivel INTEGER CHECK (nivel >= 1 AND nivel <= 50), tipo VARCHAR(50));', 4, NULL, '20.1: Tabla con constraints', 1, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (95, 20, 'Crea función que calcule XP necesaria.', 'CREATE FUNCTION xp_para_nivel(target INTEGER) RETURNS INTEGER AS '' SELECT target * 10; '' LANGUAGE SQL; SELECT xp_para_nivel(15);', 4, NULL, '20.2: Función de cálculo', 2, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (96, 20, 'Crea vista con aventureros y total de oro.', 'CREATE VIEW resumen_heroes AS SELECT a.nombre, a.clase, COALESCE(SUM(e.precio), 0) AS total_oro FROM aventureros a LEFT JOIN equipamiento e ON a.id_aventurero = e.id_aventurero GROUP BY a.id_aventurero, a.nombre, a.clase;', 5, NULL, '20.3: Vista de resumen', 3, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (77, 14, 'Crea trigger que muestre mensaje al insertar.', 'CREATE OR REPLACE FUNCTION fn_saludo() RETURNS TRIGGER AS $$ BEGIN RAISE NOTICE ''Nuevo aventurero: %'', NEW.nombre; RETURN NEW; END; $$ LANGUAGE plpgsql; DROP TRIGGER IF EXISTS trg_saludo ON aventureros; CREATE TRIGGER trg_saludo AFTER INSERT ON aventureros FOR EACH ROW EXECUTE FUNCTION fn_saludo();', 5, NULL, '14.1: Trigger básico', 1, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (97, 20, 'Inserta aventurero con equipo en transacción.', 'BEGIN; INSERT INTO aventureros (nombre, clase, nivel) VALUES (''Final'', ''Paladín'', 25); INSERT INTO equipamiento (id_aventurero, item, precio) VALUES (currval(''aventureros_id_aventurero_seq''), ''Espada Final'', 500); COMMIT;', 5, NULL, '20.4: Transacción segura', 4, 'HISTORIA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
