INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (102, 8, 'Nivel entre 10 y 30.', 'SELECT * FROM aventureros WHERE nivel BETWEEN 10 AND 30;', 1, NULL, 'Rápida: BETWEEN clásico', 201, 'RAPIDA', 'editor') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (103, 8, 'Quién tiene nivel NULL.', 'SELECT nombre FROM aventureros WHERE nivel IS NULL;', 1, NULL, 'Rápida: NULL especial', 202, 'RAPIDA', 'editor') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (98, 5, 'Añade una restricción matemática a la tabla aventureros. Asegúrate de que nadie pueda tener un nivel de cero o negativo utilizando ADD CHECK (nivel > 0).', 'ALTER TABLE aventureros ADD CHECK (nivel > 0);', 1, '{"tipo_validacion": "ddl"}', 'Rápida: CHECK rápido', 201, 'RAPIDA', 'editor') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (99, 5, 'Busca los nombres duplicados en la tabla. Agrupa los registros por nombre y muestra el "nombre" y el "COUNT(*)" de aquellos cuyo conteo sea mayor a 1 utilizando HAVING.', 'SELECT nombre, COUNT(*) FROM aventureros GROUP BY nombre HAVING COUNT(*) > 1;', 2, NULL, 'Rápida: Nombres duplicados', 202, 'RAPIDA', 'editor') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
INSERT INTO lms_core.ejercicios_practicos (id_ejercicio, id_modulo, enunciado, query_maestra, dificultad, configuracion_extra, titulo, orden, tipo_mision, formato) OVERRIDING SYSTEM VALUE VALUES (100, 6, 'Un cliente VIP acaba de llegar. Inserta una nueva reserva relacionando al huésped 1 con la habitación 1. Al igual que antes, asegúrate de que tu instrucción "retorne" toda la fila (*) para que podamos ver la fecha que se generó por defecto.', 'INSERT INTO reservas (id_huesped, id_habitacion) VALUES (1, 1) RETURNING *;', 2, '{"tipo_validacion": "ddl"}', 'Rápida: DEFAULT fecha', 201, 'RAPIDA', 'sql') ON CONFLICT (id_ejercicio) DO UPDATE SET id_modulo = EXCLUDED.id_modulo, enunciado = EXCLUDED.enunciado, query_maestra = EXCLUDED.query_maestra, dificultad = EXCLUDED.dificultad, configuracion_extra = EXCLUDED.configuracion_extra, titulo = EXCLUDED.titulo, orden = EXCLUDED.orden, tipo_mision = EXCLUDED.tipo_mision, formato = EXCLUDED.formato;
